interface ZapierWebhookPayload {
  [key: string]: string | number | boolean | null;
}

async function triggerZap(payload: ZapierWebhookPayload): Promise<void> {
  const webhookUrl = process.env.ZAPIER_WEBHOOK_URL;
  if (!webhookUrl) {
    throw new Error('ZAPIER_WEBHOOK_URL environment variable is not set');
  }

  const response = await fetch(webhookUrl, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(payload),
  });

  if (!response.ok) {
    throw new Error(`Zapier webhook request failed: ${response.status} ${response.statusText}`);
  }

  // Zapier responds with plain text 'Accepted' on success
  const body = await response.text();
  console.log('Zap triggered:', body);
}

// Example: trigger a Zap when a user signs up
await triggerZap({
  event: 'user.signed_up',
  email: 'jane@example.com',
  name: 'Jane Smith',
  plan: 'free',
  signedUpAt: new Date().toISOString(),
});
// Zapier will now execute all action steps in the Zap:
// e.g., add row to Google Sheets, send Slack notification, create HubSpot contact

import express, { Request, Response } from 'express';

interface ZapierWebhookBody {
  event?: string;
  [key: string]: unknown;
}

const app = express();
app.use(express.json());

// Zapier sends data to your app using the 'Webhooks by Zapier' action
// Configure the Zap to POST to your endpoint URL
app.post('/webhooks/zapier', (req: Request, res: Response): void => {
  const body = req.body as ZapierWebhookBody;

  console.log('Received Zapier webhook:', body);

  // Zapier checks for a 2xx status to consider the action successful
  // If you return 4xx/5xx, Zapier will retry and eventually mark the task errored
  const event = body.event ?? 'unknown';

  switch (event) {
    case 'new_lead':
      // Handle new CRM lead forwarded from HubSpot via Zapier
      console.log('New lead received from Zapier:', body);
      break;
    case 'payment_received':
      // Handle payment notification forwarded from Stripe via Zapier
      console.log('Payment notification from Zapier:', body);
      break;
    default:
      console.log('Unhandled Zapier event:', event);
  }

  // Always return 200 quickly — Zapier has a short timeout (~10s)
  res.status(200).json({ received: true });
});

app.listen(3000, () => console.log('Listening for Zapier webhooks on port 3000'));
